    taxonomy: tax("Arthropoda", "节肢动物门", "Insecta", "昆虫纲", "Hemiptera", "半翅目", "Membracidae", "角蝉科", "Bocydium", "球冠角蝉属"),
    taxonomySource: ["World Auchenorrhyncha Database", "https://hoppers.speciesfile.org/otus/55093"],
